     4	/**
     5	 * A class representing shared characteristics of animals.
     6	 *
     7	 * @version 2022.03.02
     8	 */
     9	public abstract class Animal extends MobileForager implements Edible
    10	{
    11	    private static final TargetAcquisitionPolicy TARGET_POLICY = new AnimalTargetAcquisitionPolicy();
    12	
    13	    protected int age;
    14	    protected boolean isNocturnal;
    15	    protected int foodLevel;
    16	    protected Gender sex;
    17	
    18	    // An animal is either male or female 
    19	    protected enum Gender {
    20	        MALE,
    21	        FEMALE
    22	    }
    23	    // An animal's chance of contracting a disease at birth
    24	    private static final double RANDOM_CONTRACTION_RATE = 0.002;
    25	
    26	
    27	    // Declaring abstract methods to obtain fields used by subclasses.
    28	    // These methods are implemented by each species.
    29	    protected abstract double BREEDING_AGE();
    30	    protected abstract int MAX_LITTER_SIZE();
    31	    protected abstract double BREEDING_PROBABILITY();
    32	    protected abstract int MAX_AGE();
    33	    protected abstract int MAX_FOOD_LEVEL();
    34	    protected abstract Set<Class<?>> DIET();
    35	
    36	
    37	    /**
    38	     * Create a new animal at location in field.
    39	     *
    40	     * @param field The field currently occupied.
    41	     * @param location The location within the field.
    42	     * @param randomAge The animal's random starting age.
    43	     * @param sex The animal's gender. 
    44	     */
    45	    public Animal(Field field, Location location, boolean randomAge, Gender sex)
    46	    {
    47	        super(field, location);
    48	        this.sex = sex;
    49	        if(randomAge) {
    50	            this.age = rand.nextInt(MAX_AGE());
    51	            foodLevel = rand.nextInt(MAX_FOOD_LEVEL());
    52	        }
    53	        else {
    54	            this.age = 0;
    55	            foodLevel = MAX_FOOD_LEVEL();
    56	        }
    57	        randomlyContractDisease();
    58	    }
    59	
    60	    /**
    61	     * Make this animal act - that is: make it do
    62	     * whatever it wants/needs to do.
    63	     * @param newAnimals A list to receive newly born animals.
    64	     * @param environment The environment that the animal resides in.
    65	     */
    66	    public void act(List<Actor> newAnimals, Environment environment)
    67	    {
    68	        randomlyContractDisease();
    69	        incrementAge();
    70	        incrementHunger();
    71	        if(isAlive()) {
    72	            giveBirth(newAnimals, environment);
    73	            forageAndMove();
    74	
    75	            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
    76	                // every step, check if the Animal is diseased
    77	                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
    78	                setDead();
    79	            }
    80	
    81	        }
    82	    }
    83	
    84	    /**
    85	     * Returns true if an animal contracts a disease at birth.
    86	     * Returns false if otherwise. 
    87	     */
    88	    protected void randomlyContractDisease()
    89	    {
    90	        if(rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
    91	            setDisease(new Disease());
    92	        }
    93	    }
    94	
    95	    /**
    96	     * Check whether this animal is to give birth at this step.
    97	     * New births will be made into free adjacent locations.
    98	     * @param newAnimals A list to return newly born animals.
    99	     * @param environment The environment that the animal resides in. 
   100	     */
   101	    protected abstract void giveBirth(List<Actor> newAnimals, Environment environment);
   102	
   103	    @Override
   104	    protected Location locateTargetLocation()
   105	    {
   106	        return TARGET_POLICY.acquireTarget(this);
   107	    }
   108	
   109	    /**
   110	     * Returns true if the animal is awake or not.
   111	     */
   112	    public boolean isAwake(Environment environment)
   113	    {
   114	        if(isNocturnal){
   115	            return !environment.getTime().isDay();
   116	        }
   117	        return environment.getTime().isDay();
   118	    }
   119	
   120	    /**
   121	     * Generates a number representing the number of births,
   122	     * if it can breed.
   123	     * @return The number of births (may be zero)
   124	     */
   125	    protected int breed()
   126	    {
   127	        int births = 0;
   128	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY()) {
   129	            births = rand.nextInt(MAX_LITTER_SIZE()) + 1;
   130	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
   131	            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
   132	                this.setDisease(mate.getDisease());
   133	            }
   134	        }
   135	        return births;
   136	    }
   137	
   138	    /**
   139	     * Returns true if the animal is able to breed.
   140	     * Returns false if otherwise. 
   141	     */
   142	    protected boolean canBreed()
   143	    {
   144	        return (age >= BREEDING_AGE() && getPotentialMates().size() > 0);
   145	    }
   146	
   147	    /**
   148	     * Returns a list of potential mates. Mates have to be
   149	     * of a opposite gender. 
   150	     * @return List<Organism> A list of potential mates.
   151	     */
   152	    protected List<Organism> getPotentialMates()
   153	    {
   154	        List<Organism> potentialMates = new ArrayList<>();
   155	        if(getField() != null){
   156	            potentialMates = getField().adjacentLocations(getLocation()).stream()
   157	                    .map(s -> getField().getObjectAt(s))
   158	                    .filter(s -> s != null)
   159	                    .filter(s -> s.getClass().equals(this.getClass()))
   160	                    .filter(s -> this.sex != ((Animal) s).sex)
   161	                    .map(s -> (Organism) s)
   162	                    .collect(Collectors.toList());
   163	            // stream counts the number of Animals of the same species, as well as opposite gender
   164	        }
   165	        return potentialMates;
   166	    }
   167	
   168	
   169	    /**
   170	     * Increase the age. This could result in the animal's death.
   171	     */
   172	    protected void incrementAge()
   173	    {
   174	        this.age++;
   175	        if(this.age > MAX_AGE()) {
   176	            setDead();
   177	        }
   178	    }
   179	
   180	    /**
   181	     * Make this animal more hungry. This could result in the animal's death.
   182	     */
   183	    protected void incrementHunger()
   184	    {
   185	        foodLevel--;
   186	        if(foodLevel <= 0) {
   187	            setDead();
   188	        }
   189	    }
   190	
   191	    /**
   192	     * Returns the food value of this animal.
   193	     */
   194	    public abstract int getFoodValue();
   195	
   196	}

