     3	/**
     4	 * Animal-specific target acquisition logic.
     5	 */
     6	public final class AnimalTargetAcquisitionPolicy implements TargetAcquisitionPolicy
     7	{
     8	    @Override
     9	    public Location acquireTarget(MobileForager forager)
    10	    {
    11	        Animal animal = (Animal) forager;
    12	        contractDiseaseFromAdjacentOrganisms(animal);
    13	
    14	        Location foodLocation = AdjacentTargetSearch.findMatchingLocation(
    15	                animal.getField(),
    16	                animal.getLocation(),
    17	                occupant -> occupant instanceof Edible && animal.DIET().contains(occupant.getClass())
    18	        );
    19	        if(foodLocation == null) {
    20	            return null;
    21	        }
    22	
    23	        Organism food = (Organism) animal.getField().getObjectAt(foodLocation);
    24	        if (food.isDiseased()
    25	                && food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE
    26	                && food.getDisease().getPropagationRate() <= Randomizer.getRandom().nextDouble())
    27	        {
    28	            animal.setDisease(food.getDisease());
    29	        }
    30	        if(food.isAlive())
    31	        {
    32	            food.setDead();
    33	            int newFoodLevel = animal.foodLevel + ((Edible) food).getFoodValue();
    34	            animal.foodLevel = Math.min(newFoodLevel, animal.MAX_FOOD_LEVEL());
    35	        }
    36	        return foodLocation;
    37	    }
    38	
    39	    private void contractDiseaseFromAdjacentOrganisms(Animal animal)
    40	    {
    41	        Field field = animal.getField();
    42	        List<Location> adjacent = field.adjacentLocations(animal.getLocation());
    43	        for(Location loc : adjacent){
    44	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
    45	                Organism organism = (Organism) field.getObjectAt(loc);
    46	                if (organism.isDiseased()
    47	                        && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT
    48	                        && organism.getDisease().getPropagationRate() <= Randomizer.getRandom().nextDouble()){
    49	                    animal.setDisease(organism.getDisease());
    50	                    break;
    51	                }
    52	            }
    53	        }
    54	    }
    55	}

