     3	/**
     4	 * Shared adjacency scan helper used by target-acquisition policies.
     5	 */
     6	public final class AdjacentTargetSearch
     7	{
     8	    private AdjacentTargetSearch()
     9	    {
    10	    }
    11	
    12	    public static Location findMatchingLocation(Field field, Location origin, Predicate<Object> matcher)
    13	    {
    14	        for(Location location : field.adjacentLocations(origin)) {
    15	            Object occupant = field.getObjectAt(location);
    16	            if(matcher.test(occupant)) {
    17	                return location;
    18	            }
    19	        }
    20	        return null;
    21	    }
    22	}

